INSERT OR IGNORE INTO question_content_sections (id,question_id,section_type,body,provenance,publication_state,answer_leak_state,reviewed_by,reviewed_at,position) SELECT 'bulk-2026-1013-why_asked','bulk-2026-1013','WHY_ASKED','People keep asking about the evolution of writing when established categories no longer fit observations, when new capabilities expose an old uncertainty, or when institutions must act before evidence is complete. The question therefore moves between specialist research and public experience, gathering different priorities as it crosses communities and historical settings.','EDITORIAL','PUBLISHED','PASSED','EDITORIAL','2026-08-11',3 WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1013');
