INSERT INTO question_search (question_id,question_text,context_summary,category_name,tags) SELECT 'bulk-2026-1041','How do institutions shape inquiry into the origin of biological complexity?','This question examines the origin of biological complexity through the changing evidence and vocabulary of science. It traces how methods, institutions, and perspectives have reframed the inquiry, identifies connections with neighbouring questions, and preserves the uncertainties that remain without presenting a proposed answer.','Science','science the-origin-of evidence' WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1041') AND NOT EXISTS (SELECT 1 FROM question_search WHERE question_id='bulk-2026-1041');
