INSERT OR IGNORE INTO question_content_sections (id,question_id,section_type,body,provenance,publication_state,answer_leak_state,reviewed_by,reviewed_at,position) SELECT 'bulk-2026-1080-origins','bulk-2026-1080','ORIGINS','Questions about technology governance first took shape through practical experience, inherited knowledge, and attempts to compare recurring patterns. The present formulation belongs to a later vocabulary: archives, institutions, and specialized methods gradually separated concerns that earlier communities often treated together, while leaving important continuities open to interpretation.','EDITORIAL','PUBLISHED','PASSED','EDITORIAL','2026-08-11',1 WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1080');
