INSERT INTO question_search (question_id,question_text,context_summary,category_name,tags) SELECT 'bulk-2026-1113','How do institutions shape inquiry into musical interpretation?','This question examines musical interpretation through the changing evidence and vocabulary of arts & humanities. It traces how methods, institutions, and perspectives have reframed the inquiry, identifies connections with neighbouring questions, and preserves the uncertainties that remain without presenting a proposed answer.','Arts & Humanities','arts-humanities musical-interpretation evidence' WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1113') AND NOT EXISTS (SELECT 1 FROM question_search WHERE question_id='bulk-2026-1113');
