INSERT INTO question_search (question_id,question_text,context_summary,category_name,tags) SELECT 'bulk-2026-1180','What can comparisons reveal about scientific measurement?','This question examines scientific measurement through the changing evidence and vocabulary of science. It traces how methods, institutions, and perspectives have reframed the inquiry, identifies connections with neighbouring questions, and preserves the uncertainties that remain without presenting a proposed answer.','Science','science scientific-measurement methods' WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1180') AND NOT EXISTS (SELECT 1 FROM question_search WHERE question_id='bulk-2026-1180');
