INSERT INTO question_search (question_id,question_text,context_summary,category_name,tags) SELECT 'bulk-2026-1199','What can comparisons reveal about mathematical optimization?','This question examines mathematical optimization through the changing evidence and vocabulary of mathematics. It traces how methods, institutions, and perspectives have reframed the inquiry, identifies connections with neighbouring questions, and preserves the uncertainties that remain without presenting a proposed answer.','Mathematics','mathematics mathematical-optimization methods' WHERE EXISTS (SELECT 1 FROM questions WHERE id='bulk-2026-1199') AND NOT EXISTS (SELECT 1 FROM question_search WHERE question_id='bulk-2026-1199');
